import { Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { i18n, notifyError } from '@placeos/common';
import { IconComponent, TranslatePipe } from '@placeos/components';
import { errorText } from '../error-text';
import { DialpadComponent } from '../ui/dialpad.component';
import { VideoCallStateService } from './video-call-state.service';

@Component({
    selector: 'video-call-dial-view',
    template: `
        <div class="flex justify-center">
            @if (!loading()) {
                <ng-container class="">
                    <dialpad (pressed)="addDigit($event)"></dialpad>
                    <div class="flex flex-col pt-8">
                        <p class="px-2 pt-4">
                            {{ 'APP.CONTROL.VC_ENTER_CODE' | translate }}
                        </p>
                        <div class="w-full p-2">
                            <mat-form-field
                                appearance="outline"
                                class="h-12 w-full"
                            >
                                <input
                                    matInput
                                    [(ngModel)]="dial_number"
                                    [placeholder]="
                                        'APP.CONTROL.VC_DIAL' | translate
                                    "
                                />
                            </mat-form-field>
                        </div>
                        <div class="w-full p-2">
                            <button
                                btn
                                matRipple
                                class="w-full"
                                [disabled]="!dial_number()"
                                (click)="joinConference()"
                            >
                                {{ 'APP.CONTROL.JOIN' | translate }}
                            </button>
                        </div>
                        <div class="w-full px-2">
                            @let show_pip = show_camera_pip();
                            <button
                                btn
                                matRipple
                                class="w-full"
                                (click)="toggleCamera()"
                                [class.inverse]="show_pip"
                            >
                                <div class="flex items-center space-x-4">
                                    <icon>{{
                                        !show_pip
                                            ? 'visibility_off'
                                            : 'visibility'
                                    }}</icon>
                                    <span>{{
                                        show_pip
                                            ? 'Hide Camera PIP'
                                            : 'Show Camera PIP'
                                    }}</span>
                                </div>
                            </button>
                        </div>
                    </div>
                </ng-container>
            } @else {
                <div
                    class="flex flex-col items-center justify-center space-y-2 p-16"
                >
                    <mat-spinner [diameter]="32"></mat-spinner>
                    <p>{{ 'APP.CONTROL.VC_JOINING' | translate }}</p>
                </div>
            }
        </div>
    `,
    styles: [``],
    imports: [
        FormsModule,
        MatFormFieldModule,
        MatInputModule,
        MatProgressSpinnerModule,
        TranslatePipe,
        IconComponent,
        MatRippleModule,
        DialpadComponent,
    ],
})
export class VideoCallDialViewComponent {
    private _call = inject(VideoCallStateService);

    public readonly dial_number = signal('');
    public readonly loading = signal(false);
    private readonly _show_camera_pip = this._call.show_camera_pip;
    public readonly show_camera_pip = computed(() => !!this._show_camera_pip());

    public readonly toggleCamera = async () =>
        this._call.showCameraPIP(!this.show_camera_pip());

    public addDigit(digit: string) {
        digit && digit !== '\b'
            ? this.dial_number.update((v) => v + digit)
            : this.dial_number.update((v) => v.substr(0, v.length - 1));
    }

    public async joinConference() {
        const dial_number = this.dial_number();
        if (!dial_number) return;
        this.loading.set(true);
        try {
            await this._call.dial(dial_number);
        } catch (error) {
            notifyError(
                i18n('APP.CONTROL.VC_DIAL_ERROR', { error: errorText(error) }),
            );
            return;
        } finally {
            this.loading.set(false);
        }
        this.dial_number.set('');
    }
}
